(() => {
  'use strict';

  const APP_CONFIG = window.APP_CONFIG || {};
  const PLAYGROUND_KEY = APP_CONFIG.playgroundKey || 'playground.token';
  localStorage.removeItem(APP_CONFIG.tokenKey || 'playground.user.token');
  const HIDE_INFO_COOKIE_NAME = APP_CONFIG.hideInfoCookieName || 'hide_info';
  const BASE_PATH = String(APP_CONFIG.basePath || '').replace(/\/$/, '');
  const WMS_URL = String(APP_CONFIG.wmsUrl || '').replace(/\/$/, '');
  const FEATURES = {
    pushNotifications:!!APP_CONFIG.features?.pushNotifications
  };
  const VAPID_PUBLIC_KEY = APP_CONFIG.vapidPublicKey || 'BGwoqHwV5SrixvSr9YQ58M9U5MzFZ7m5rCrWrGBmMpPVkaWbCwJtL7KWAZFTeZps_2zcdguI1_R-ZtgpLIzPu6Y';
  const ERRORS = [
    'Es wurden keine Kontrollberichte empfangen.','Es wurden Kontrollberichte ohne Inspektionsdatum geliefert.',
    'Für diesen Spielplatz ist am selben Tag bereits ein Bericht mit derselben Inspektionsart eingereicht worden.',
    'Interner Server-Fehler.','Es wurden keine Mängel geliefert.','Es wurden keine Spielgeräte geliefert.',
    'Es wurde ein leeres Bildgeliefert','Die Objekt-ID (UUID) fehlt.',
    'Ein Spielgerät, das nicht geprüft werden muss, wurde an den Webservice zur Prüfung gesendet.',
    'Änderung nicht gespeichert, da nicht ausreichend Benutzerdaten angegeben wurden.',
    'Für Mängel der Priorität B sind Dringlichkeit, Zuständigkeit/Typ und Zuständigkeit/Person Pflichtfelder.',
    'Die angemeldete Person ist für diesen Spielplatz und diese Inspektionsart nicht berechtigt.',
    'Mindestens ein übermitteltes Spielgerät gehört nicht zum ausgewählten Spielplatz.'
  ];
  const RESPONSIBILITIES = [
    'Revier Mitte','Revier Süd','Revier West','Revier Ost','Dispo',
    'Revier','Spielplatzverantwortlicher','Projektleiter'
  ];
  const content = document.querySelector('#content');
  const state = {user:null, selectedPlayground:null, inspectionType:'', users:[], playgrounds:[]};

  function withBase(path='/') { if(/^https?:\/\//i.test(path))return path; const value=path.startsWith('/')?path:`/${path}`; return `${BASE_PATH}${value}` || '/'; }
  function stripBase(path) { if(!BASE_PATH)return path||'/'; if(path===BASE_PATH)return '/'; return path.startsWith(BASE_PATH + '/')?path.slice(BASE_PATH.length):path; }
  function esc(value='') { return String(value ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c])); }
  function attr(value='') { return esc(value).replace(/`/g,'&#096;'); }
  function fmtDate(value, time=false) {
    if (!value || String(value).startsWith('0001')) return '';
    const d=new Date(value); if(Number.isNaN(d.getTime())) return '';
    return new Intl.DateTimeFormat('de-CH', time?{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}:{day:'2-digit',month:'2-digit',year:'numeric'}).format(d);
  }
  function fmtDateTime(value){if(!value)return '';const d=new Date(value);return Number.isNaN(d.getTime())?String(value):d.toLocaleString('de-CH',{dateStyle:'short',timeStyle:'short'});}
  function errorText(obj) { let text=obj?.errorMessage||''; if(text.startsWith('SPK-')){const n=Number(text.split('-')[1]);text=`${ERRORS[n]} (${text})`;} return text; }
  function toast(message, ms=4000) { const el=document.querySelector('#snackbar');el.textContent=message;el.classList.remove('hidden');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.add('hidden'),ms); }
  function prepareUser(user){if(!user)return null;const last=String(user.lastName||'');return{...user,initials:last.length>1?(last[0]+last[1]).toUpperCase():'AN'};}
  async function api(path, options={}) {
    const headers={'Content-Type':'application/json',...(options.headers||{})};
    const response=await fetch(withBase(path),{...options,headers,credentials:'same-origin'});if(!response.ok){const text=await response.text();const e=new Error(text||response.statusText);e.status=response.status;throw e;}
    if(response.status===204||response.headers.get('content-length')==='0')return null;
    const type=response.headers.get('content-type')||'';return type.includes('json')?response.json():response.blob();
  }
  function updateShell(){
    const logged=!!state.user;
    document.querySelector('#login-button').classList.toggle('hidden',logged);document.querySelector('#user-chip').classList.toggle('hidden',!logged);
    document.querySelector('#private-nav').classList.toggle('hidden',!logged);document.querySelector('#users-nav').classList.toggle('hidden',!logged||state.user?.role!=='administrator');
    document.querySelector('#inspections-nav').classList.toggle('hidden',!logged||state.user?.role==='maintenance');
    document.querySelector('#notifications-nav').classList.toggle('hidden',!logged||!FEATURES.pushNotifications);
    if(logged)document.querySelector('#user-chip').textContent=state.user.initials;
  }
  function navigate(path, replace=false){const target=withBase(stripBase(path));(replace?history.replaceState:history.pushState).call(history,{},'',target);renderRoute();if(innerWidth<=599)document.querySelector('#sidenav').classList.remove('open');}
  function requireLogin(){if(!state.user){navigate('/login',true);return false;}return true;}
  function page(title, body){return `<div class="page"><h1 class="page-title">${title}</h1>${body}</div>`;}
  function field(label,name,value='',type='text',extra=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${attr(value)}" ${extra}></label>`;}
  function selectField(label,name,options,value='',extra='',hint=''){return `<label class="field"><span>${label}</span><select name="${name}" ${extra}>${options.map(o=>`<option value="${attr(o.value)}" ${String(o.value)===String(value)?'selected':''}>${esc(o.label)}</option>`).join('')}</select>${hint?`<small class="field-hint">${esc(hint)}</small>`:''}</label>`;}

  async function openPlaygroundDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open('PlaygroundDB',1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('playgrounds'))req.result.createObjectStore('playgrounds');};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
  async function storePlayground(pg){state.selectedPlayground=pg;try{const db=await openPlaygroundDb();const tx=db.transaction('playgrounds','readwrite');tx.objectStore('playgrounds').put(pg,PLAYGROUND_KEY);}catch(e){console.error(e);}}
  async function loadStoredPlayground(){try{const db=await openPlaygroundDb();return await new Promise((resolve,reject)=>{const r=db.transaction('playgrounds').objectStore('playgrounds').get(PLAYGROUND_KEY);r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>reject(r.error);});}catch{return null;}}
  async function clearPlayground(){state.selectedPlayground=null;try{const db=await openPlaygroundDb();db.transaction('playgrounds','readwrite').objectStore('playgrounds').delete(PLAYGROUND_KEY);}catch{}}

  function renderWelcome(){content.innerHTML=`<div class="hero"><h1>Stadtgrün Winterthur</h1><h2>Department Technische Betriebe</h2></div><div class="welcome"><h3>Willkommen ${state.user?`${esc(state.user.firstName)} ${esc(state.user.lastName)} `:''}im System für die Spielplatzkontrolle der Stadt Winterthur</h3>${!state.user?'<p>Falls Sie ein durch die Stadtverwaltung Winterthur <b>akkreditierter Kontrolleur</b> sind, erhalten Sie ein Abbonement auf diese Applikation. Sie müssen sich <b>einloggen</b>, um die Funktionen dieser Applikation verwenden zu können. Falls Sie noch über <b>keine Login-Daten</b> verfügen, wenden Sie sich bitte an die Stadtverwaltung. Zum einloggen verwenden Sie bitte den <b>Login-Button</b> in der <b>oberen rechten Ecke</b>.</p>':''}<p>Sobald Sie eingeloggt sind, gelangen Sie im linken Applikations-Menü zu den <b>Prüfprozessen für die einzelnen Spielgeräte</b> eines Spielplatzes. Bevor Sie auf die Spielgeräte zugreifen können, müssen Sie einen <b>Spielplatz</b> im Menü-Punkt <i>Spielplatz</i> festlegen.</p><p>Diese Applikation ist <b>responsiv</b>, sie funktioniert dadurch auf diversen Endgeräten, z.B. sowohl auf einem Desktop-PC, einem Laptop als auch auf einem Smartphone. Die Darstellung passt sich der jeweiligen Bildschirmgrösse an. Des Weiteren ist diese Applikation <b>nicht offline-fähig</b>, Sie müssen permanente Internetverbindung haben um sie zu nutzen.</p><p style="font-size:.8em">v ${esc(window.APP_VERSION)}</p></div>`;}
  function renderLogin(){content.innerHTML=`<div class="login-form"><form id="login-form"><h2>Anmeldung</h2><div id="login-error" class="error hidden">Benutzername oder Passphrase ungültig.</div>${field('Benutzername','loginname','','email','required autofocus')}${field('Passphrase','password','','password','required')}<button class="button toolbar-login" type="submit">LOGIN</button></form></div>`;document.querySelector('#login-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const result=await api('/account/login',{method:'POST',body:JSON.stringify({mailAddress:f.get('loginname'),passPhrase:f.get('password')})});state.user=prepareUser(result.user);await clearPlayground();updateShell();navigate('/');}catch{document.querySelector('#login-error').classList.remove('hidden');}};}

  async function playgroundPicker(mode){
    const crossHairAssetImage=new Image();
    crossHairAssetImage.src=withBase('/static/assets/crosshair.png');
    const title=mode==='overview'?'Basisdaten Spielgeräte':mode==='defect'?'Mängel':'Inspektion';
    content.innerHTML=page(title,`<div id="picker-controls"></div><div id="picker-result"></div>`);
    let types=[];if(mode==='inspection')types=await api('/inspection/types');
    const controls=document.querySelector('#picker-controls');
    controls.innerHTML=`${mode==='inspection'?selectField('Art der Inspektion','inspectionType',[{value:'',label:''},...types.map(x=>({value:x,label:x}))],state.inspectionType,'required'):''}<label class="field playground-autocomplete" style="min-width:70%"><span>Spielplatzname</span><input id="playground-search" autocomplete="off" role="combobox" aria-autocomplete="list" aria-controls="playground-options" aria-expanded="false"><div id="playground-options" class="autocomplete-panel hidden" role="listbox"></div></label>${mode==='defect'?'<label class="checkbox"><input id="only-defects" type="checkbox"> Nur Spielplätze mit Mängeln auflisten</label>':''}`;
    const search=controls.querySelector('#playground-search');const options=controls.querySelector('#playground-options');let activeOption=-1;let visiblePlaygrounds=[];
    async function loadNames(){const inspection=mode==='inspection'?controls.querySelector('[name=inspectionType]').value:'Keine Inspektion';if(mode==='inspection'){state.inspectionType=inspection;await clearPlayground();search.value='';if(!inspection){state.playgrounds=[];hideOptions();return;}}state.playgrounds=await api(`/playground/onlynames?inspectiontype=${encodeURIComponent(inspection)}`);refreshOptions();}
    function optionText(p){if(mode==='inspection'){let text=p.name;if(p.dateOfLastInspection&&!String(p.dateOfLastInspection).startsWith('0001'))text+=` (${fmtDate(p.dateOfLastInspection)})`;if(p.inspectionSuspended)text+=' (ausgesetzt)';return text;}if(mode==='defect'&&p.hasOpenDeviceDefects)return `${p.name} (Mangel)`;return p.name;}
    function hideOptions(){options.classList.add('hidden');search.setAttribute('aria-expanded','false');activeOption=-1;}
    function refreshOptions(){const only=controls.querySelector('#only-defects')?.checked;const needle=search.value.trim().toLowerCase();visiblePlaygrounds=state.playgrounds.filter(p=>(!only||p.hasOpenDeviceDefects)&&(!needle||p.name.toLowerCase().includes(needle)));activeOption=visiblePlaygrounds.length?0:-1;options.innerHTML=visiblePlaygrounds.map((p,i)=>`<div class="autocomplete-option${i===activeOption?' active':''}" role="option" aria-selected="${i===activeOption}" data-index="${i}">${esc(optionText(p))}</div>`).join('');if(document.activeElement===search&&visiblePlaygrounds.length){options.classList.remove('hidden');search.setAttribute('aria-expanded','true');}else hideOptions();}
    function setActive(index){if(!visiblePlaygrounds.length)return;activeOption=(index+visiblePlaygrounds.length)%visiblePlaygrounds.length;options.querySelectorAll('.autocomplete-option').forEach((el,i)=>{el.classList.toggle('active',i===activeOption);el.setAttribute('aria-selected',i===activeOption?'true':'false');});options.querySelector(`[data-index="${activeOption}"]`)?.scrollIntoView({block:'nearest'});}
    async function selectPlayground(name){name=(name||'').trim();if(!name)return;if(mode==='defect')controls.querySelector('#only-defects').checked=false;search.value=name;hideOptions();const pg=await api(`/playground/byname?name=${encodeURIComponent(name)}&inspectiontype=${encodeURIComponent(mode==='inspection'?state.inspectionType:'Keine Inspektion')}&withdefects=${mode==='defect'||mode==='overview'}&withinspections=${mode==='inspection'}`);if(mode!=='overview')await storePlayground(pg);renderPickedPlayground(pg,mode);history.replaceState({},'',`${location.pathname}?playground_name=${encodeURIComponent(name)}`);}
    if(mode==='inspection')controls.querySelector('[name=inspectionType]').onchange=loadNames;if(mode==='defect')controls.querySelector('#only-defects').onchange=refreshOptions;
    search.addEventListener('focus',refreshOptions);search.addEventListener('input',refreshOptions);search.addEventListener('blur',()=>setTimeout(hideOptions,0));search.addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();if(options.classList.contains('hidden'))refreshOptions();else setActive(activeOption+1);}else if(e.key==='ArrowUp'){e.preventDefault();if(options.classList.contains('hidden'))refreshOptions();else setActive(activeOption-1);}else if(e.key==='Enter'&&activeOption>=0){e.preventDefault();selectPlayground(visiblePlaygrounds[activeOption].name);}else if(e.key==='Escape'){hideOptions();}});options.addEventListener('mousedown',e=>{const option=e.target.closest('.autocomplete-option');if(!option)return;e.preventDefault();selectPlayground(visiblePlaygrounds[Number(option.dataset.index)].name);});
    await loadNames();const initial=new URLSearchParams(location.search).get('playground_name');if(initial){search.value=initial.trim();await selectPlayground(search.value);}
  }

  function evaluateDevice(device){const p=device.properties;const criteria=[...(p.generalInspectionCriteria||[]),...(p.mainFallProtectionInspectionCriteria||[]),...(p.secondaryFallProtectionInspectionCriteria||[])];p.hasChecks=criteria.length>0;p.hasOpenChecks=criteria.some(c=>!c.currentInspectionReport.inspectionDone||!c.currentInspectionReport.maintenanceDone);p.hasOpenDefects=!!p.hasOpenDefects||(p.defects||[]).some(d=>!d.dateDone);}
  function renderPickedPlayground(pg,mode){const target=document.querySelector('#picker-result');if(!target)return;for(const d of pg.playdevices||[])evaluateDevice(d);target.innerHTML=`<h2 style="font-weight:300">${esc(pg.name)}</h2>${mode==='inspection'&&pg.dateOfLastInspection&&fmtDate(pg.dateOfLastInspection)===fmtDate(new Date())?'<div class="info-box warning">Achtung, dieser Spielplatz wurde heute bereits geprüft.</div>':''}${mode==='overview'?renderDocuments(pg):''}<div class="cards">${(pg.playdevices||[]).map(d=>deviceCard(d,mode)).join('')}</div>${mode==='inspection'&&pg.playdevices.length?'<div style="margin:1em"><button id="finish-inspection" class="button success">ABSCHLIESSEN</button></div>':''}`;bindDeviceCards(pg,mode);if(mode==='inspection'){const finish=document.querySelector('#finish-inspection');const update=()=>{finish.disabled=!canFinish(pg);};update();target.addEventListener('change',update);finish.onclick=()=>sendInspection(pg);}}
  function shortDocumentName(name){const value=String(name||'');return value.length>8?`${value.slice(0,8)}...`:value;}
  function documentItems(pg,type){const rich=type==='abnahme'?pg.documentsOfAcceptance:pg.certificateDocuments;if(Array.isArray(rich)&&rich.length)return rich;const fids=type==='abnahme'?pg.documentsOfAcceptanceFids:pg.certificateDocumentsFids;return (fids||[]).map(fid=>({fid,name:String(fid)}));}
  function renderDocumentBox(pg,type,title,cssClass){const items=documentItems(pg,type),admin=state.user?.role==='administrator';if(!items.length&&!admin)return '';return `<div class="document-box ${cssClass}"><h4>${title}</h4><div class="document-actions">${items.map(doc=>`<span class="document-item"><button class="button doc" data-id="${doc.fid}" data-type="${type}" title="${attr(doc.name)}">${esc(shortDocumentName(doc.name))}</button>${admin?`<button class="button secondary doc-rename" data-id="${doc.fid}" data-type="${type}" data-name="${attr(doc.name)}">UMBENENNEN</button><button class="button danger doc-delete" data-id="${doc.fid}" data-type="${type}" data-name="${attr(doc.name)}">LÖSCHEN</button>`:''}</span>`).join(' ')}${admin?`<label class="button primary document-upload-label">HOCHLADEN<input class="document-upload hidden" type="file" accept="application/pdf,.pdf" data-type="${type}"></label>`:''}</div></div>`;}
  function renderDocuments(pg){return `${renderDocumentBox(pg,'abnahme','Abnahmedokumente','acceptance')}${renderDocumentBox(pg,'zertifikat','Zertifikatsdokumente','certificate')}`;}
  function deviceCard(device,mode){const p=device.properties;const year=new Date().getFullYear();const renovation=p.recommendedYearOfRenovation;const hasDate=p.constructionDate&&new Date(p.constructionDate).getFullYear()!==1;let chip='';if(p.cannotBeChecked||p.notToBeChecked)chip='<span class="chip inactive">inaktiv</span>';else if(p.hasChecks)chip=`<button class="chip ${p.hasOpenChecks?'pending':'done'} toggle-checks">${p.hasOpenChecks?'pendent':'erledigt'}</button>`;else if(mode==='inspection')chip='<span class="chip neutral">keine Kontrollen</span>';
    return `<article class="card" data-fid="${p.fid}"><div class="card-header"><div><div class="card-title">${esc((p.type.description||'').slice(0,14))}${(p.type.description||'').length>14?'…':''}</div><div class="card-subtitle">${esc((p.type.name||'').slice(0,20))}${(p.type.name||'').length>20?'…':''}</div></div><div class="chips">${chip}</div></div><div class="tabs"><button class="tab active" data-tab="photo">Foto</button><button class="tab" data-tab="map">Karte</button></div><div class="tab-panel photo-panel"><img class="device-image" src="${withBase(`/playdevice/${p.fid}/Picture?dryRun=false&t=${Date.now()}`)}" alt="Foto des Spielgeräts">${mode==='overview'&&!p.notToBeChecked?'<small>Foto ersetzen...</small><input class="device-photo" type="file" accept="image/png">':''}</div><div class="tab-panel map-panel hidden"><a title="Link auf Kartenausschnitt Spielgerät" target="_blank" href="https://stadtplan.winterthur.ch/mini?gbapp=portal&topic=Spielplatzkarte&infoactive=1&maponly=1&onlymap=1&scale=200&x=${device.geometry.coordinates[0]}&y=${device.geometry.coordinates[1]}&back=Hintergrundkarte_LK_AV_Situationsplan"><img class="map-image" title="Kartenausschnitt des Spielgeräts" src="${esc(WMS_URL)}?LAYERS=AV_UEP_Landeskarten,Spielplatz&VERSION=1.1.1&DPI=96&TRANSPARENT=TRUE&FORMAT=image%2Fpng&SERVICE=WMS&REQUEST=GetMap&STYLES=&SRS=EPSG%3A2056&BBOX=${device.geometry.coordinates[0]-10},${device.geometry.coordinates[1]-5},${device.geometry.coordinates[0]+10},${device.geometry.coordinates[1]+5}&WIDTH=800&HEIGHT=400"></a></div><div class="card-content">${mode!=='defect'?`<p><b>Norm (Jahrgang)</b>: <i>${esc(p.type.standard||'Nicht angegeben')}</i></p><p><b>Lieferant</b>: <i>${esc(p.supplier||'unbekannt')}</i></p><p><b>Erstellungsjahr</b>: <i>${hasDate?new Date(p.constructionDate).getFullYear():'unbekannt'}</i></p>`:''}${mode==='overview'?`<div class="field"><span>Empfohlenes Sanierungsjahr</span><input class="renovation-year" type="number" min="${year}" max="9999" value="${renovation||''}"></div>${selectField('Sanierungsart','renovation',[{value:'0',label:''},{value:'1',label:'Totalsanierung'},{value:'2',label:'Teilsanierung'}],String(p.renovationType||0))}<label class="field"><span>Kommentar zum empf. Sanierungsjahr</span><textarea class="renovation-comment" maxlength="255">${esc(p.commentRecommendedYearOfRenovation||'')}</textarea></label>`:''}<p>${mode==='defect'&&p.hasOpenDefects?'<span class="status-label orange">Hat offene Mängel</span>':mode!=='defect'?(renovation?`<span class="status-label ${renovation-year<=1?'red':'orange'}">Sanierung ausstehend</span>`:'<span class="status-label green">Keine Sanierung geplant</span>'):''}</p>${mode==='inspection'&&p.hasOpenDefects?'<p><span class="status-label red">Hat offene Mängel</span></p>':''}</div>${(mode==='defect'||mode==='overview')?(p.defects||[]).map(d=>`<div class="card-actions">${esc(d.defectDescription)} <button class="button primary open-defect" data-tid="${d.tid}">ÖFFNEN</button></div>`).join(''):''}<div class="card-actions ${mode==='overview'?'device-main-actions':''}">${mode==='inspection'?'<button class="button primary open-device">ÖFFNEN</button>':mode==='defect'?'<button class="button primary new-defect">NEUER MANGEL</button>':'<button class="button primary save-device">SPEICHERN</button><button class="button secondary new-defect">NEUER MANGEL</button>'}</div></article>`;}
  function bindDeviceCards(pg,mode){
    document.querySelectorAll('.card[data-fid]').forEach(card=>{const fid=Number(card.dataset.fid),device=pg.playdevices.find(d=>d.properties.fid===fid),p=device.properties;
      card.querySelectorAll('.tab').forEach(btn=>btn.onclick=()=>{card.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===btn));card.querySelector('.photo-panel').classList.toggle('hidden',btn.dataset.tab!=='photo');card.querySelector('.map-panel').classList.toggle('hidden',btn.dataset.tab!=='map');});
      const toggle=card.querySelector('.toggle-checks');if(toggle)toggle.onclick=()=>{const activate=p.hasOpenChecks;allCriteria(p).forEach(c=>{c.currentInspectionReport.inspectionDone=activate;c.currentInspectionReport.maintenanceDone=activate;});evaluateDevice(device);renderPickedPlayground(pg,mode);storePlayground(pg);};
      card.querySelector('.open-device')?.addEventListener('click',()=>navigate(`/deviceattributes/playdevice/${fid}`));card.querySelector('.new-defect')?.addEventListener('click',()=>navigate(`/defect/${fid}/0`));card.querySelectorAll('.open-defect').forEach(b=>b.onclick=()=>navigate(`/defect/${fid}/${b.dataset.tid}`));
      card.querySelector('.save-device')?.addEventListener('click',async()=>{p.recommendedYearOfRenovation=Number(card.querySelector('.renovation-year').value)||0;p.renovationType=Number(card.querySelector('[name=renovation]').value)||0;p.commentRecommendedYearOfRenovation=card.querySelector('.renovation-comment').value;const r=await api('/playdevice/',{method:'POST',body:JSON.stringify(device)});toast(errorText(r)||'Spielgerät erfolgreich gespeichert');});
      card.querySelector('.device-photo')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;const data=await resizeImage(await readFile(file),1200,800);const r=await api(`/playdevice/?fid=${fid}`,{method:'PUT',body:JSON.stringify({data})});if(errorText(r))toast(errorText(r));else{card.querySelector('.device-image').src=withBase(`/playdevice/${fid}/Picture?t=${Date.now()}`);toast('Bild erfolgreich hochgeladen');}});
    });
    document.querySelectorAll('.doc').forEach(btn=>btn.onclick=()=>downloadPdfDocument(btn.dataset.id,btn.dataset.type));
    document.querySelectorAll('.document-upload').forEach(input=>input.onchange=async()=>{const file=input.files?.[0];if(!file)return;if(file.type&&file.type!=='application/pdf'&&!file.name.toLowerCase().endsWith('.pdf')){toast('Es können nur PDF-Dokumente hochgeladen werden.');input.value='';return;}try{const dataUrl=await readFile(file);const contentBase64=String(dataUrl).split(',',2)[1]||'';const result=await api('/document/',{method:'POST',body:JSON.stringify({playgroundId:pg.id,type:input.dataset.type,name:file.name,contentBase64})});const target=input.dataset.type==='abnahme'?'documentsOfAcceptance':'certificateDocuments';pg[target]=[...(pg[target]||[]),result];const fids=input.dataset.type==='abnahme'?'documentsOfAcceptanceFids':'certificateDocumentsFids';pg[fids]=[...(pg[fids]||[]),result.fid];await storePlayground(pg);renderPickedPlayground(pg,mode);toast('Dokument erfolgreich hochgeladen');}catch(e){toast(e.message||'Dokument konnte nicht hochgeladen werden.');}finally{input.value='';}});
    document.querySelectorAll('.doc-rename').forEach(btn=>btn.onclick=async()=>{const current=btn.dataset.name||'',name=window.prompt('Neuer Dokumentname',current);if(name===null)return;const trimmed=name.trim();if(!trimmed){toast('Der Dokumentname darf nicht leer sein.');return;}try{const result=await api(`/document/${btn.dataset.id}/name?type=${encodeURIComponent(btn.dataset.type)}`,{method:'PUT',body:JSON.stringify({name:trimmed})});const target=btn.dataset.type==='abnahme'?'documentsOfAcceptance':'certificateDocuments';const doc=(pg[target]||[]).find(x=>String(x.fid)===String(btn.dataset.id));if(doc)doc.name=result.name;await storePlayground(pg);renderPickedPlayground(pg,mode);toast('Dokument erfolgreich umbenannt');}catch(e){toast(e.message||'Dokument konnte nicht umbenannt werden.');}});
    document.querySelectorAll('.doc-delete').forEach(btn=>btn.onclick=async()=>{const name=btn.dataset.name||btn.dataset.id;if(!window.confirm(`Dokument "${name}" wirklich löschen?`))return;try{await api(`/document/${btn.dataset.id}?type=${encodeURIComponent(btn.dataset.type)}`,{method:'DELETE'});const target=btn.dataset.type==='abnahme'?'documentsOfAcceptance':'certificateDocuments';pg[target]=(pg[target]||[]).filter(x=>String(x.fid)!==String(btn.dataset.id));const fids=btn.dataset.type==='abnahme'?'documentsOfAcceptanceFids':'certificateDocumentsFids';pg[fids]=(pg[fids]||[]).filter(fid=>String(fid)!==String(btn.dataset.id));await storePlayground(pg);renderPickedPlayground(pg,mode);toast('Dokument erfolgreich gelöscht');}catch(e){toast(e.message||'Dokument konnte nicht gelöscht werden.');}});
  }
  async function downloadPdfDocument(fid,type){
    const browserTab=window.open();
    try{
      const blob=await api(`/document/${fid}?type=${encodeURIComponent(type)}`,{headers:{Accept:'application/pdf'}});
      const objectUrl=URL.createObjectURL(blob);
      if(browserTab)browserTab.location.href=objectUrl;
      else window.open(objectUrl);
      window.setTimeout(()=>URL.revokeObjectURL(objectUrl),60000);
    }catch{
      if(browserTab)browserTab.close();
      toast('Fehler beim Download des PDF-Dokuments.');
    }
  }
  const allCriteria=p=>[...(p.generalInspectionCriteria||[]),...(p.mainFallProtectionInspectionCriteria||[]),...(p.secondaryFallProtectionInspectionCriteria||[])];
  function canFinish(pg){return (pg.playdevices||[]).every(d=>{const p=d.properties;if(p.notToBeChecked)return true;if(p.cannotBeChecked)return !!p.cannotBeCheckedReason?.trim();evaluateDevice(d);return !p.hasOpenChecks;});}
  async function sendInspection(pg){const reports=[];for(const d of pg.playdevices){const p=d.properties;if(p.notToBeChecked||p.cannotBeChecked)continue;for(const [criteria,fall] of [[p.generalInspectionCriteria,''],[p.mainFallProtectionInspectionCriteria,'Hauptfallschutz'],[p.secondaryFallProtectionInspectionCriteria,'Nebenfallschutz']])for(const c of criteria||[]){const r=c.currentInspectionReport;r.playdeviceFid=p.fid;r.inspectionText=c.check;r.maintenanceText=c.maintenance;r.fallProtectionType=fall;r.inspectionType=state.inspectionType;reports.push(r);}}try{const result=await api('/inspection/',{method:'POST',body:JSON.stringify(reports)});const error=errorText(result);toast(error||'Prüfbericht erfolgreich gespeichert');if(!error){await clearPlayground();state.inspectionType='';navigate('/inspections');}}catch{toast('Unbekannte Fehlermeldung, evtl. schlechte Internetverbindung');}}

  async function renderDeviceAttributes(fid){
    let pg=state.selectedPlayground||await loadStoredPlayground();
    const device=pg?.playdevices?.find(d=>d.properties.fid===fid);
    if(!device){content.innerHTML=page('',`<p class="error">Der Spielplatz dieses Spielgeräts ist nicht gewählt. Bitte wählen Sie zunächst den Spielplatz aus, auf dem dieses Spielgerät sich befindet.</p>`);return;}
    state.selectedPlayground=pg;
    const p=device.properties;
    evaluateDevice(device);
    const numberOfCriteria=(p.generalInspectionCriteria?.length||0)+(p.mainFallProtectionInspectionCriteria?.length||0)+(p.secondaryFallProtectionInspectionCriteria?.length||0);
    const inspectionTypes=pg.inspectionTypeOptions||[];
    const selectedLastInspectionType=inspectionTypes[0]||'';
    const selectedNextToLastInspectionType=inspectionTypes[0]||'';
    const currentInspection=`${p.hasChecks?`<p style="font-size:150%;color:purple"><b>Inspektionsart:</b> ${esc(state.inspectionType)}</p><p><b>Kontrolleur:</b> ${esc(state.user.firstName)} ${esc(state.user.lastName)}<br><b>Datum der Inspektion:</b> ${fmtDate(new Date())}</p><div class="section"><label class="checkbox"><input id="cannot-check" type="checkbox" ${p.cannotBeChecked?'checked':''}> Nicht prüfbar</label><label id="cannot-reason-field" class="field ${p.cannotBeChecked?'':'hidden'}"><span>Begründung, weshalb das Gerät nicht prüfbar ist</span><textarea id="cannot-reason" maxlength="255" required>${esc(p.cannotBeCheckedReason||'')}</textarea></label><button id="save-can-check" class="button primary">SPEICHERN</button></div><div id="inspection-warning" class="info-box warning ${p.cannotBeChecked?'hidden':''}">ACHTUNG! Prüfungen müssen immer gemäss den vorliegenden Anweisungen und gemäss der Montageanleitung für das jeweilige Produkt erfolgen.</div>`:'<div class="info-box success-box">Es sind keine Prüfungen zu diesem Gerät vorhanden oder aktiv.</div>'}<div id="criteria" class="criteria ${p.cannotBeChecked?'hidden':''}">${criterionSection('Allgemeine Inspektionskriterien',p.generalInspectionCriteria)}${criterionSection('Inspektionskriterien zum Hauptfallschutz',p.mainFallProtectionInspectionCriteria)}${criterionSection('Inspektionskriterien zum Nebenfallschutz',p.secondaryFallProtectionInspectionCriteria)}</div>`;
    const tabs=[`<button class="tab active" type="button" data-inspection-tab="current">Aktuelle Kontrolle (${numberOfCriteria})</button>`];
    const panels=[`<div class="tab-panel inspection-tab-panel" data-inspection-panel="current">${currentInspection}</div>`];
    if(p.lastInspectionReports?.length){tabs.push('<button class="tab" type="button" data-inspection-tab="last">Letzte Kontrolle</button>');panels.push(`<div class="tab-panel inspection-tab-panel hidden" data-inspection-panel="last">${oldReports(p.lastInspectionReports,inspectionTypes,selectedLastInspectionType,'last')}</div>`);}
    if(p.nextToLastInspectionReports?.length){tabs.push('<button class="tab" type="button" data-inspection-tab="next">Vorletzte Kontrolle</button>');panels.push(`<div class="tab-panel inspection-tab-panel hidden" data-inspection-panel="next">${oldReports(p.nextToLastInspectionReports,inspectionTypes,selectedNextToLastInspectionType,'next')}</div>`);}
    content.innerHTML=page(`Prüfung Spielgerät: ${esc(p.type.description)}`,`<div class="tabs inspection-tabs">${tabs.join('')}</div>${panels.join('')}`);
    document.querySelectorAll('[data-inspection-tab]').forEach(tab=>tab.onclick=()=>{document.querySelectorAll('[data-inspection-tab]').forEach(x=>x.classList.toggle('active',x===tab));document.querySelectorAll('[data-inspection-panel]').forEach(panel=>panel.classList.toggle('hidden',panel.dataset.inspectionPanel!==tab.dataset.inspectionTab));});
    document.querySelectorAll('.old-inspection-type').forEach(select=>select.onchange=()=>{const panel=select.closest('[data-inspection-panel]');panel.querySelectorAll('[data-old-inspection-type]').forEach(report=>report.classList.toggle('hidden',report.dataset.oldInspectionType!==select.value));});
    const cannot=document.querySelector('#cannot-check');if(cannot)cannot.onchange=()=>{p.cannotBeChecked=cannot.checked;document.querySelector('#cannot-reason-field').classList.toggle('hidden',!p.cannotBeChecked);document.querySelector('#criteria').classList.toggle('hidden',p.cannotBeChecked);document.querySelector('#inspection-warning').classList.toggle('hidden',p.cannotBeChecked);storePlayground(pg);};document.querySelector('#cannot-reason')?.addEventListener('change',e=>{p.cannotBeCheckedReason=e.target.value;storePlayground(pg);});document.querySelector('#save-can-check')?.addEventListener('click',async()=>{const r=await api('/playdevice/',{method:'POST',body:JSON.stringify(device)});toast(errorText(r)||'Spielgerät erfolgreich gespeichert');});
    document.querySelectorAll('[data-criterion]').forEach(el=>{const [group,index,fieldName]=el.dataset.criterion.split(':');const c=p[group][Number(index)];el.onchange=()=>{c.currentInspectionReport[fieldName]=el.type==='checkbox'?el.checked:el.value;storePlayground(pg);const summary=el.closest('details').querySelector('summary');summary.classList.toggle('complete',c.currentInspectionReport.inspectionDone&&c.currentInspectionReport.maintenanceDone);};});
  }
  function criterionSection(title,criteria=[]){if(!criteria?.length)return'';return `<h2>${title}</h2>${criteria.map((c,i)=>{const group=c===criteria[i]?'':'';return criterion(c,i,title.includes('Haupt')?'mainFallProtectionInspectionCriteria':title.includes('Neben')?'secondaryFallProtectionInspectionCriteria':'generalInspectionCriteria');}).join('')}`;}
  function criterion(c,i,group){const r=c.currentInspectionReport,complete=r.inspectionDone&&r.maintenanceDone;return `<details><summary class="${complete?'complete':''}"><b>${esc(c.realm)}${c.checkShortText?' – '+esc(c.checkShortText):''}</b> <span class="status-label ${complete?'green':'red'}">${complete?'ERLEDIGT':'PENDENT'}</span></summary><div class="criterion-grid"><div class="criterion-column"><h3>Prüfung</h3><div class="criterion-instruction"><b>Prüfung:</b> ${esc(c.check)}</div><label class="checkbox"><input type="checkbox" data-criterion="${group}:${i}:inspectionDone" ${r.inspectionDone?'checked':''}> Prüfung erledigt</label><label class="field"><span>Kommentar zur Prüfung</span><textarea maxlength="255" data-criterion="${group}:${i}:inspectionComment">${esc(r.inspectionComment)}</textarea></label></div><div class="criterion-column"><h3>Wartung</h3><div class="maintenance-instruction">➔ <b>Wartung:</b> ${esc(c.maintenance)}</div><label class="checkbox"><input type="checkbox" data-criterion="${group}:${i}:maintenanceDone" ${r.maintenanceDone?'checked':''}> Wartung erledigt</label><label class="field"><span>Kommentar zur Wartung</span><textarea maxlength="255" data-criterion="${group}:${i}:maintenanceComment">${esc(r.maintenanceComment)}</textarea></label></div></div></details>`;}
  function oldReports(reports,inspectionTypes,selectedInspectionType,group){
    const options=inspectionTypes.map(type=>`<option value="${esc(type)}" ${type===selectedInspectionType?'selected':''} class="${reports.some(r=>r.inspectionType===type)?'available-report':''}">${esc(type)}</option>`).join('');
    return `<div class="old-inspection-type-box"><p>Bitte wählen Sie die Art der Inspektion:</p><label class="field"><span>Art der Inspektion</span><select class="old-inspection-type" data-old-inspection-select="${group}" required>${options}</select></label></div>${reports.map(r=>`<article class="old-report ${r.inspectionType===selectedInspectionType?'':'hidden'}" data-old-inspection-type="${esc(r.inspectionType)}"><h2>${esc(r.inspectionText||'[Diese Inspektion hat keinen Titel]')}</h2><div class="report-grid"><div><h4>Metadaten</h4><p><b>Inspektionsart:</b> ${esc(r.inspectionType)}</p><p><b>Kontrolleur:</b> ${esc(r.inspector)}</p><p><b>Datum der Inspektion:</b> ${fmtDate(r.dateOfService)}</p><p><b>Fallschutz:</b> ${esc(r.fallProtectionType||'nein')}</p></div><div><h4>Prüfung</h4><p><b>Prüfung Text:</b><br>${esc(r.inspectionText||'[Die Prüfung dieser Inspektion hat keinen Text]')}</p><label class="checkbox"><input type="checkbox" disabled ${r.inspectionDone?'checked':''}> Prüfung erledigt</label><p><b>Prüfung Kommentar:</b><br>${esc(r.inspectionComment||'[Kein Kommentar]')}</p></div><div><h4>Wartung</h4><p><b>Wartung Text:</b><br>${esc(r.maintenanceText||'[Die Wartung dieser Inspektion hat keinen Text]')}</p><label class="checkbox"><input type="checkbox" disabled ${r.maintenanceDone?'checked':''}> Wartung erledigt</label><p><b>Wartung Kommentar:</b><br>${esc(r.maintenanceComment||'[Kein Kommentar]')}</p></div></div></article>`).join('')}`;
  }

  async function renderDefectOverview(){
    const defects=await api('/defect/overview');
    let sortKey='dateCreation',sortDirection=1;
    const priorityLabel=value=>({1:'A (sofort)',2:'B (mittelfristig)',3:'C (im Folgejahr beurteilen)'})[Number(value)]||'–';
    const responsibilityLabel=value=>({1:'Revier',2:'Spielplatzverantwortlicher',3:'Projektleiter'})[Number(value)]||'–';
    const ageDays=value=>{if(!value)return null;const date=new Date(value);if(Number.isNaN(date.getTime()))return null;return Math.max(0,Math.floor((Date.now()-date.getTime())/86400000));};
    content.innerHTML=page('Mängel',`<div class="defect-overview-controls"><label class="field"><span>Suche</span><input id="defect-filter-text" type="search" placeholder="Spielplatz, Gerät, Beschrieb, Zuständigkeit …"></label><label class="field"><span>Status</span><select id="defect-filter-status"><option value="all">Alle</option><option value="open" selected>Offen</option><option value="done">Erledigt</option></select></label><label class="field"><span>Dringlichkeit</span><select id="defect-filter-priority"><option value="all">Alle</option><option value="1">A (sofort)</option><option value="2">B (mittelfristig)</option><option value="3">C (im Folgejahr beurteilen)</option><option value="none">Ohne Angabe</option></select></label></div><div class="defect-overview-summary" id="defect-overview-summary"></div><div class="defect-table-wrap"><table class="table defect-table"><thead><tr><th><button data-sort="status">Status</button></th><th><button data-sort="playgroundName">Spielplatz</button></th><th><button data-sort="playdeviceType">Geräteart</button></th><th><button data-sort="playdeviceFid">Geräte-FID</button></th><th><button data-sort="priority">Dringlichkeit</button></th><th><button data-sort="dateCreation">Erfasst am</button></th><th><button data-sort="age">Offen seit</button></th><th><button data-sort="responsibility">Zuständigkeit</button></th><th><button data-sort="defectDescription">Beschrieb</button></th><th>Bemerkung</th><th>Bearbeiten</th></tr></thead><tbody id="defect-overview-body"></tbody></table></div>`);
    content.querySelector('.page').classList.add('defect-overview-page');
    const body=document.querySelector('#defect-overview-body'),summary=document.querySelector('#defect-overview-summary');
    function valueForSort(d,key){if(key==='status')return d.done?1:0;if(key==='priority')return Number(d.priority)||99;if(key==='age')return ageDays(d.dateCreation)??-1;if(key==='responsibility')return `${responsibilityLabel(d.defectsResponsibleBodyId)} ${d.responsibleUserName||''}`.toLowerCase();if(key==='dateCreation')return d.dateCreation?new Date(d.dateCreation).getTime():0;const value=d[key];return typeof value==='number'?value:String(value||'').toLowerCase();}
    function draw(){
      const text=document.querySelector('#defect-filter-text').value.trim().toLowerCase(),status=document.querySelector('#defect-filter-status').value,priority=document.querySelector('#defect-filter-priority').value;
      let rows=defects.filter(d=>{if(status==='open'&&d.done)return false;if(status==='done'&&!d.done)return false;if(priority!=='all'){if(priority==='none'){if(Number(d.priority)>0)return false;}else if(Number(d.priority)!==Number(priority))return false;}if(text){const haystack=[d.playgroundName,d.playdeviceType,d.playdeviceFid,d.standard,priorityLabel(d.priority),responsibilityLabel(d.defectsResponsibleBodyId),d.responsibleUserName,d.defectDescription,d.defectComment].join(' ').toLowerCase();if(!haystack.includes(text))return false;}return true;});
      rows.sort((a,b)=>{if(!!a.assignmentOverdue!==!!b.assignmentOverdue)return a.assignmentOverdue?-1:1;const av=valueForSort(a,sortKey),bv=valueForSort(b,sortKey);if(av<bv)return -1*sortDirection;if(av>bv)return 1*sortDirection;return 0;});
      const open=rows.filter(d=>!d.done).length,overdue=rows.filter(d=>d.assignmentOverdue).length;summary.textContent=`${rows.length} Mängel angezeigt · ${open} offen · ${rows.length-open} erledigt${overdue?` · ${overdue} kritisch: Auftrag > 24 h nicht angenommen`:''}`;
      body.innerHTML=rows.length?rows.map(d=>{const age=d.done?null:ageDays(d.dateCreation);const responsibility=[responsibilityLabel(d.defectsResponsibleBodyId),d.responsibleUserName].filter(x=>x&&x!=='–').join(' · ')||'–';return `<tr class="${d.assignmentOverdue?'defect-assignment-overdue':''}"><td><span class="defect-status ${d.done?'done':'open'}">${d.done?'Erledigt':'Offen'}</span>${d.assignmentOverdue?'<span class="defect-overdue-badge">24 h überschritten</span>':''}</td><td>${esc(d.playgroundName||'–')}</td><td>${esc(d.playdeviceType||'–')}</td><td>${d.playdeviceFid||'–'}</td><td>${esc(priorityLabel(d.priority))}</td><td>${esc(fmtDate(d.dateCreation)||'–')}</td><td>${d.done?'–':age===null?'–':`${age} Tage`}</td><td>${esc(responsibility)}</td><td class="defect-description-cell">${esc(d.defectDescription||'–')}</td><td>${esc(d.defectComment||'–')}</td><td><button class="button primary open-defect-row" data-device="${d.playdeviceFid}" data-tid="${d.tid}">ÖFFNEN</button></td></tr>`;}).join(''):'<tr><td colspan="11" class="defect-table-empty">Keine Mängel entsprechen den gewählten Filtern.</td></tr>';
      document.querySelectorAll('.open-defect-row').forEach(button=>button.onclick=()=>navigate(`/defect/${button.dataset.device}/${button.dataset.tid}`));
      document.querySelectorAll('.defect-table th button').forEach(button=>{button.classList.toggle('active-sort',button.dataset.sort===sortKey);button.dataset.direction=button.dataset.sort===sortKey?(sortDirection===1?'asc':'desc'):'';});
    }
    document.querySelectorAll('#defect-filter-text,#defect-filter-status,#defect-filter-priority').forEach(input=>input.addEventListener(input.tagName==='INPUT'?'input':'change',draw));
    document.querySelectorAll('.defect-table th button').forEach(button=>button.onclick=()=>{const key=button.dataset.sort;if(sortKey===key)sortDirection*=-1;else{sortKey=key;sortDirection=1;}draw();});
    draw();
  }

  async function renderDefect(fid,tid){
    const users=await api('/account/users/assignable');let defect=tid>0?await api(`/defect/?tid=${tid}`):{tid:0,playdeviceFid:fid,priority:0,done:false,defectPicsTids:[],defectPicsAfterFixingTids:[],defectDescription:'',dateCreation:new Date().toISOString(),dateDone:null,defectComment:'',defectsResponsibleBodyId:-1,responsibleUserFid:-1,assignmentStatus:'',assignmentComment:'',infoMailSentAt:null,infoMailRecipientName:'',createdByFid:state.user?.fid||-1,createdByName:state.user?`${state.user.firstName} ${state.user.lastName}`.trim():'',assignmentHistory:[]};let savedResponsible=defect.responsibleUserFid;
    function draw(){const priorityTwo=Number(defect.priority)===2;content.innerHTML=`<div class="defect-page"><p class="eyebrow">Mängelerfassung</p><h1>${defect.tid?`Mangel ${defect.tid}`:'Neuer Mangel'}</h1><p class="meta-line">Erstellt am: ${fmtDate(defect.dateCreation)} · Erstellt durch: ${esc(defect.createdByName||'Nicht verfügbar')}</p><section class="section"><h2>Beschrieb des Mangels</h2><label class="field" style="max-width:none"><textarea id="defect-description" maxlength="255" rows="3">${esc(defect.defectDescription)}</textarea></label></section><div class="select-grid defect-fields-grid">${selectField(`Dringlichkeit${priorityTwo?' *':''}`,'priority',[{value:'',label:'Bitte auswählen'},{value:1,label:'A (sofort)'},{value:2,label:'B (mittelfristig)'},{value:3,label:'C (im Folgejahr beurteilen)'}],defect.priority)}${selectField(`Zuständigkeit/Typ${priorityTwo?' *':''}`,'body',[{value:'',label:'Keine Angabe'},{value:1,label:'Revier'},{value:2,label:'Spielplatzverantwortlicher'},{value:3,label:'Projektleiter'}],defect.defectsResponsibleBodyId)}<div class="responsibility-person-stack">${selectField(`Zuständigkeit/Person${priorityTwo?' *':''}`,'responsible',[{value:'',label:'Keine Person auswählen'},...users.map(u=>({value:u.fid,label:`${u.firstName} ${u.lastName}`}))],defect.responsibleUserFid,'','Empfänger:in der Infomail')}${assignmentPanel(defect,users)}${assignmentHistoryPanel(defect.assignmentHistory||[])}</div></div>${priorityTwo?'<p class="section-hint">* Pflichtfeld bei Priorität B (mittelfristig)</p>':''}<div class="defect-grid defect-content-grid">${photoPanel('Fotos des Mangels',defect.defectPicsTids,false,defect.tid)}<section class="section completion-section"><h2>Erledigung</h2><label class="checkbox"><input id="defect-done" type="checkbox" ${defect.done?'checked':''}> Mangel erledigt</label><dl class="detail-list"><div><dt>Datum der Erledigung</dt><dd>${defect.dateDone?fmtDate(defect.dateDone):'Noch nicht erledigt'}</dd></div><div><dt>Erledigt durch</dt><dd>${defect.dateDone?esc(defect.doneByName||'Nicht verfügbar'):'Noch nicht erledigt'}</dd></div></dl><label class="field"><span>Bemerkung zur Erledigung</span><textarea id="defect-comment" maxlength="255">${esc(defect.defectComment)}</textarea></label></section>${defect.done||defect.defectPicsAfterFixingTids.length?photoPanel('Fotos nach Mangelbeseitigung',defect.defectPicsAfterFixingTids,true,defect.tid):''}</div><div class="button-row"><button id="save-defect" class="button primary">${defect.tid?'SPEICHERN':'ANLEGEN'}</button>${defect.tid&&Number(defect.responsibleUserFid)>0&&Number(defect.responsibleUserFid)===Number(savedResponsible)?'<button id="info-mail" class="button primary">INFOMAIL SENDEN</button>':''}${defect.infoMailSentAt&&defect.infoMailRecipientName?`<small>${esc(`versendet an ${defect.infoMailRecipientName} am ${fmtDate(defect.infoMailSentAt)}`)}</small>`:''}</div></div>`;bind();}
    function bind(){const sync=()=>{defect.defectDescription=document.querySelector('#defect-description').value;defect.priority=Number(document.querySelector('[name=priority]').value)||0;defect.defectsResponsibleBodyId=Number(document.querySelector('[name=body]').value)||-1;defect.responsibleUserFid=Number(document.querySelector('[name=responsible]').value)||-1;defect.defectComment=document.querySelector('#defect-comment').value;const assignmentComment=document.querySelector('#assignment-comment');if(assignmentComment)defect.assignmentComment=assignmentComment.value;defect.done=document.querySelector('#defect-done').checked;if(defect.done&&!defect.dateDone)defect.dateDone=new Date().toISOString();if(!defect.done)defect.dateDone=null;};document.querySelector('[name=priority]').onchange=()=>{sync();draw();};document.querySelector('#defect-done').onchange=()=>{sync();draw();};document.querySelector('#save-defect').onclick=async()=>{sync();if(defect.priority===2&&(defect.defectsResponsibleBodyId<1||defect.responsibleUserFid<1)){toast(ERRORS[10]);return;}try{if(defect.tid){const r=await api('/defect/',{method:'POST',body:JSON.stringify(defect)});const e=errorText(r);if(e)toast(e);else{defect=await api(`/defect/?tid=${defect.tid}`);savedResponsible=defect.responsibleUserFid;toast('Mangel erfolgreich aktualisiert');draw();}}else{const r=await api('/defect/',{method:'PUT',body:JSON.stringify(defect)});const e=errorText(r);if(e)toast(e);else{defect=r;savedResponsible=defect.responsibleUserFid;toast('Mangel erfolgreich angelegt');draw();}}}catch{toast('Unbekannter Fehler, evtl. schlechte Internetverbindung');}};document.querySelectorAll('.upload-defect-photo').forEach(input=>input.onchange=async e=>{const file=e.target.files[0];if(!file)return;const full=await resizeImage(await readFile(file),1200,800),thumb=await cropSquare(full);const result=await api(`/defect/picture/${defect.tid}`,{method:'PUT',body:JSON.stringify({base64StringPicture:full,base64StringPictureThumb:thumb,afterFixing:e.target.dataset.after==='true'})});(e.target.dataset.after==='true'?defect.defectPicsAfterFixingTids:defect.defectPicsTids).push(result.tid);toast('Bild hochgeladen');draw();});document.querySelector('#accept-assignment')?.addEventListener('click',async()=>{sync();try{const r=await api(`/defect/${defect.tid}/accept`,{method:'POST',body:JSON.stringify(defect)});const e=errorText(r);if(e){toast(e);return;}defect=await api(`/defect/?tid=${defect.tid}`);toast('Auftrag angenommen');draw();}catch{toast('Auftrag konnte nicht angenommen werden');}});document.querySelector('#reject-assignment')?.addEventListener('click',async()=>{sync();try{const r=await api(`/defect/${defect.tid}/reject`,{method:'POST',body:JSON.stringify(defect)});const e=errorText(r);if(e){toast(e);return;}defect=await api(`/defect/?tid=${defect.tid}`);toast('Auftrag abgelehnt');draw();}catch{toast('Auftrag konnte nicht abgelehnt werden');}});document.querySelector('#info-mail')?.addEventListener('click',async e=>{sync();const button=e.currentTarget;button.disabled=true;button.textContent='INFOMAIL WIRD GESENDET…';try{const updated=await api(`/defect/${defect.tid}/send-mail`,{method:'POST',body:'{}'});defect.infoMailSentAt=updated.infoMailSentAt;defect.infoMailRecipientName=updated.infoMailRecipientName;toast('Infomail wurde an den Mailserver übergeben');draw();}catch(err){toast(`Infomail konnte nicht gesendet werden: ${err.message||'Unbekannter Fehler'}`);}finally{if(document.body.contains(button)){button.disabled=false;button.textContent='INFOMAIL SENDEN';}}});}
    draw();
  }
  function photoPanel(title,tids,after,defectTid){const persisted=Number(defectTid)>0;return `<section class="section photo-section ${after?'after-section':''}"><h2>${title}</h2>${!after&&!persisted?'<p class="section-hint">Fotos können nach dem Anlegen des Mangels hochgeladen werden.</p>':''}${persisted&&!tids.length?'<p class="empty-hint">Noch keine Fotos vorhanden.</p>':''}${persisted&&tids.length<3?`<input class="upload-defect-photo" data-after="${after}" type="file" accept="image/png">`:''}<div class="image-grid">${tids.map(id=>`<a href="${withBase(`/defect/picture/${id}?thumb=false`)}" target="_blank"><img src="${withBase(`/defect/picture/${id}?thumb=true`)}"></a>`).join('')}</div></section>`;}
  function isAssignmentForCurrentUser(d,users){if(!d||Number(d.responsibleUserFid)<=0||!state.user)return false;if(Number(state.user.fid)===Number(d.responsibleUserFid))return true;const assigned=users.find(u=>Number(u.fid)===Number(d.responsibleUserFid)),assignedMail=String(assigned?.mailAddress||'').trim().toLowerCase(),currentMail=String(state.user.mailAddress||'').trim().toLowerCase();return !!assignedMail&&!!currentMail&&assignedMail===currentMail;}
  function assignmentPanel(d,users){const assigned=users.find(u=>Number(u.fid)===Number(d.responsibleUserFid)),assignedName=assigned?`${assigned.firstName||''} ${assigned.lastName||''}`.trim():'',hasAssignment=Number(d.responsibleUserFid)>0,canAct=d.tid!==0&&isAssignmentForCurrentUser(d,users)&&d.assignmentStatus!=='angenommen';return `<section class="section assignment-section${hasAssignment?'':' is-empty'}"><div class="assignment-title-row"><h2>Auftrag</h2>${hasAssignment?`<span class="status-chip status-${d.assignmentStatus==='angenommen'?'accepted':d.assignmentStatus==='abgelehnt'?'rejected':'assigned'}">${esc(d.assignmentStatus==='angenommen'?'angenommen':d.assignmentStatus==='abgelehnt'?'abgelehnt':'zugewiesen')}</span>`:''}</div>${!hasAssignment?'<p class="empty-hint">Keine zuständige Person zugewiesen.</p>':`<dl class="detail-list"><div><dt>Zuständige Person</dt><dd>${esc(assignedName)}</dd></div>${d.dateAssignmentCreated?`<div><dt>Zugewiesen am</dt><dd>${esc(fmtDateTime(d.dateAssignmentCreated))}</dd></div>`:''}${d.dateAssignmentAccepted?`<div><dt>Angenommen am</dt><dd>${esc(fmtDateTime(d.dateAssignmentAccepted))}</dd></div>`:''}${d.dateAssignmentRejected?`<div><dt>Abgelehnt am</dt><dd>${esc(fmtDateTime(d.dateAssignmentRejected))}</dd></div>`:''}</dl><label class="field assignment-comment-field"><span>Bemerkung zum Auftrag</span><textarea id="assignment-comment" maxlength="255" rows="2" placeholder="Bemerkung zum Auftrag...">${esc(d.assignmentComment||'')}</textarea></label>${canAct?'<div class="button-row assignment-actions"><button id="accept-assignment" class="button primary">AUFTRAG ANNEHMEN</button><button id="reject-assignment" class="button danger">AUFTRAG ABLEHNEN</button></div>':''}`}</section>`;}
  function assignmentHistoryPanel(history){const count=history.length;if(!count)return `<details class="assignment-history-section"><summary>Zuweisungshistorie <span class="assignment-history-count">0</span></summary><p class="empty-hint">Noch keine Änderungen der zuständigen Person vorhanden.</p></details>`;return `<details class="assignment-history-section"><summary>Zuweisungshistorie <span class="assignment-history-count">${count}</span></summary><div class="assignment-history${count>5?' assignment-history-scrollable':''}">${history.map(item=>{const previous=item.previousUserName||'Keine Zuweisung',next=item.newUserName||'Keine Zuweisung',by=item.changedByName?` · geändert durch ${esc(item.changedByName)}`:'';return `<div class="assignment-history-item"><div class="assignment-history-date">${esc(fmtDateTime(item.changedAt))}${by}</div><div><b>${esc(previous)}</b><span class="material-icons assignment-history-arrow">arrow_forward</span><b>${esc(next)}</b></div></div>`;}).join('')}</div></details>`;}
  function roleLabel(role){return role==='inspector'?'Kontrolleur':role==='maintenance'?'Wartung':'Administrator';}
  async function renderUsers(){const users=await api('/account/users/');content.innerHTML=page('Benutzeradministration',`<p>Hier können Sie Benutzer dieses Systems freischalten, deaktivieren oder bearbeiten.</p><label class="checkbox"><input id="show-inactive" type="checkbox"> Inaktive Benutzer einblenden</label><label id="only-new-label" class="checkbox hidden"><input id="only-new" type="checkbox"> Nur neue Benutzer anzeigen</label><div id="users-table"></div>`);const draw=()=>{const show=document.querySelector('#show-inactive').checked,only=document.querySelector('#only-new').checked;document.querySelector('#only-new-label').classList.toggle('hidden',!show);const rows=users.filter(u=>show?(only?u.isNew:true):u.active);document.querySelector('#users-table').innerHTML=`<table class="table"><thead><tr><th></th><th>Vorname</th><th>Nachname</th><th class="hide-mobile">E-Mail-Adresse</th><th>Rolle</th><th>Zuständigkeit</th><th>Aktiv</th></tr></thead><tbody>${rows.map(u=>`<tr><td><a class="edit-icon material-icons" href="${withBase(`/users/${encodeURIComponent(u.mailAddress)}`)}" data-route>edit_square</a></td><td>${esc(u.firstName)}</td><td>${esc(u.lastName)}</td><td class="hide-mobile">${esc(u.mailAddress)}</td><td>${esc(roleLabel(u.role))}</td><td>${esc(u.responsibility||'')}</td><td><input type="checkbox" disabled ${u.active?'checked':''}></td></tr>`).join('')}</tbody></table>`;bindRouteLinks();};document.querySelector('#show-inactive').onchange=draw;document.querySelector('#only-new').onchange=draw;draw();}
  async function renderUser(email){const arr=await api(`/account/users/?email=${encodeURIComponent(email)}`),user=arr[0];if(!user){content.innerHTML=page('Benutzerdaten','<div class="error">Benutzer existiert nicht.</div>');return;}if(user.isNew){user.isNew=false;await api('/account/users/?changepassphrase=false',{method:'PUT',body:JSON.stringify(user)});}const responsibilities=[...RESPONSIBILITIES];if(user.responsibility&&!responsibilities.includes(user.responsibility))responsibilities.push(user.responsibility);content.innerHTML=page(`Benutzerdaten <span style="font-weight:normal">/ ${esc(user.firstName)}</span>`,`<div class="two-columns"><div class="flat-card">${field('Nachname','lastName',user.lastName)}${field('Vorname','firstName',user.firstName)}${field('E-Mail-Adresse','email',user.mailAddress,'email','disabled')}${selectField('Rolle','role',[{value:'administrator',label:'Administrator'},{value:'inspector',label:'Kontrolleur'},{value:'maintenance',label:'Wartung'}],user.role)}${selectField('Zuständigkeit','responsibility',[{value:'',label:'Keine Angabe'},...responsibilities.map(value=>({value,label:value}))],user.responsibility)}<label class="checkbox"><input name="active" type="checkbox" ${user.active?'checked':''}> Aktiv</label></div><div class="flat-card muted-panel">${field('Passphrase','password','','password')}<button id="change-password" class="button">PASSPHRASE ÄNDERN</button> <button id="delete-user" class="button">BENUTZER LÖSCHEN</button></div></div>`);const sync=()=>{user.lastName=document.querySelector('[name=lastName]').value;user.firstName=document.querySelector('[name=firstName]').value;user.role=document.querySelector('[name=role]').value;user.responsibility=document.querySelector('[name=responsibility]').value;user.active=document.querySelector('[name=active]').checked;};const save=async change=>{sync();if(change)user.passPhrase=document.querySelector('[name=password]').value;const r=await api(`/account/users/?changepassphrase=${change}`,{method:'PUT',body:JSON.stringify(user)});toast(errorText(r)|| (change?'Passwort erfolgreich geändert':'Benutzer erfolgreich aktualisiert'));};document.querySelector('[name=lastName]').onblur=()=>save(false);document.querySelector('[name=firstName]').onblur=()=>save(false);document.querySelector('[name=role]').onchange=()=>save(false);document.querySelector('[name=responsibility]').onchange=()=>save(false);document.querySelector('[name=active]').onchange=()=>save(false);document.querySelector('#change-password').onclick=()=>save(true);document.querySelector('#delete-user').onclick=async()=>{const r=await api(`/account/users/?email=${encodeURIComponent(user.mailAddress)}`,{method:'DELETE'});if(errorText(r))toast(errorText(r));else navigate('/users');};}
  function pushAvailable(){return window.SERVICE_WORKER_ENABLED!==false&&'serviceWorker' in navigator&&'PushManager' in window&&'Notification' in window&&window.isSecureContext;}
  function notificationPermission(){return 'Notification' in window?Notification.permission:'unsupported';}
  function permissionLabel(value){return value==='granted'?'Erlaubt':value==='denied'?'Blockiert':value==='default'?'Noch nicht entschieden':value==='unsupported'?'Nicht unterstützt':String(value);}
  function deviceTitle(userAgent=navigator.userAgent){if(!userAgent)return'Unbekanntes Gerät';if(/Android/i.test(userAgent))return'Android-Gerät';if(/iPhone/i.test(userAgent))return'iPhone';if(/iPad/i.test(userAgent))return'iPad';if(/Windows/i.test(userAgent))return'Windows-PC';if(/Macintosh|Mac OS/i.test(userAgent))return'Mac';if(/Linux/i.test(userAgent))return'Linux-Gerät';return'Gerät';}
  function browserLabel(userAgent=''){if(!userAgent)return'Unbekannter Browser';if(/Edg\//i.test(userAgent))return'Microsoft Edge';if(/SamsungBrowser\//i.test(userAgent))return'Samsung Internet';if(/Firefox\//i.test(userAgent))return'Firefox';if(/Chrome\//i.test(userAgent)||/CriOS\//i.test(userAgent))return'Chrome';if(/Safari\//i.test(userAgent))return'Safari';return'Browser';}
  function operatingSystemLabel(userAgent=''){if(!userAgent)return'Unbekanntes System';if(/Android/i.test(userAgent))return'Android';if(/iPhone|iPad/i.test(userAgent))return'iOS';if(/Windows/i.test(userAgent))return'Windows';if(/Macintosh|Mac OS/i.test(userAgent))return'macOS';if(/Linux/i.test(userAgent))return'Linux';return'Betriebssystem';}
  function deviceIcon(userAgent=''){if(/Android|iPhone|Mobile/i.test(userAgent))return'smartphone';if(/iPad|Tablet/i.test(userAgent))return'tablet_mac';return'computer';}
  function base64Url(buffer){if(!buffer)return'';let binary='';for(const byte of new Uint8Array(buffer))binary+=String.fromCharCode(byte);return btoa(binary).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
  function vapidKeyBytes(value){const padding='='.repeat((4-value.length%4)%4),raw=atob((value+padding).replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from(raw,c=>c.charCodeAt(0));}
  function subscriptionRegistration(subscription){return{endpoint:subscription.endpoint,p256dh:base64Url(subscription.getKey('p256dh')),auth:base64Url(subscription.getKey('auth')),userAgent:navigator.userAgent};}
  async function localPushSubscription(){if(!pushAvailable())return null;const registration=await navigator.serviceWorker.ready;return registration.pushManager.getSubscription();}
  async function renderNotifications(){
    const available=pushAvailable();let local=null,subscriptions=[];
    if(available){try{local=await localPushSubscription();}catch{local=null;}}
    try{subscriptions=await api('/PushSubscription/Me');}catch{subscriptions=[];}
    const statusTitle=!available?'Push wird nicht unterstützt':local?'Push ist auf diesem Gerät aktiv':'Push ist auf diesem Gerät nicht aktiv';
    const statusText=!available?'Dieser Browser oder diese Umgebung unterstützt aktuell keine Push-Benachrichtigungen.':local?'Dieses Gerät erhält Push-Meldungen, wenn dir ein Mangel zugewiesen wird.':'Aktiviere Push, wenn du auf diesem Gerät informiert werden möchtest.';
    content.innerHTML=`<div class="notification-page"><div class="page-header"><div><h1>Push-Benachrichtigungen</h1><p class="lead-text">Hier verwaltest du, ob dieses Gerät Push-Meldungen aus der Spielplatzkontrolle erhalten soll. Du wirst informiert, wenn dir ein neuer Mangel zur Behebung zugewiesen wurde.</p></div></div><div class="notification-grid"><section class="notification-card settings-card"><div class="card-header"><span class="material-icons">notifications_active</span><div><h2>Dieses Gerät</h2><p class="card-subtitle">Push auf dem aktuell verwendeten Gerät aktivieren oder deaktivieren.</p></div></div><div class="status-box ${available?(local?'status-ok':'status-warning'):'status-error'}"><strong>${esc(statusTitle)}</strong><span>${esc(statusText)}</span></div><div class="info-list"><div><span class="info-label">Browser-Berechtigung</span><span class="info-value">${esc(permissionLabel(notificationPermission()))}</span></div><div><span class="info-label">Gerät</span><span class="info-value">${esc(deviceTitle())}</span></div></div><div class="button-row"><button id="push-register" class="button primary" ${!available||local?'disabled':''}>AUF DIESEM GERÄT AKTIVIEREN</button><button id="push-unregister" class="button" ${!available||!local?'disabled':''}>AUF DIESEM GERÄT DEAKTIVIEREN</button></div></section><section class="notification-card devices-card"><div class="card-header"><span class="material-icons">devices</span><div><h2>Aktive Geräte</h2><p class="card-subtitle">${subscriptions.length} ${subscriptions.length===1?'Gerät ist':'Geräte sind'} aktuell registriert.</p></div></div>${subscriptions.length===0?'<div class="empty-state"><span class="material-icons">notifications_off</span><p>Es ist aktuell kein Gerät für Push-Benachrichtigungen registriert.</p></div>':`<div class="device-list">${subscriptions.map(subscription=>{const ua=subscription.userAgent||'';return`<div class="device-item"><div class="device-icon"><span class="material-icons">${deviceIcon(ua)}</span></div><div class="device-details"><div class="device-title">${esc(deviceTitle(ua))}${ua===navigator.userAgent?'<span class="current-badge">Dieses Gerät</span>':''}</div><div class="device-meta">${esc(browserLabel(ua))} · ${esc(operatingSystemLabel(ua))}</div></div></div>`;}).join('')}</div>`}</section></div></div>`;
    const register=document.querySelector('#push-register'),unregister=document.querySelector('#push-unregister');
    if(register)register.onclick=async()=>{register.disabled=true;try{if(!pushAvailable())throw new Error('Push-Benachrichtigungen werden auf diesem Gerät oder in dieser Umgebung nicht unterstützt.');if(!VAPID_PUBLIC_KEY.trim())throw new Error('Der VAPID Public Key ist im Frontend nicht konfiguriert.');const registration=await navigator.serviceWorker.ready;const subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:vapidKeyBytes(VAPID_PUBLIC_KEY)});const result=await api('/PushSubscription/Register',{method:'POST',body:JSON.stringify(subscriptionRegistration(subscription))});const error=errorText(result);if(error)toast(error);else{toast('Push-Benachrichtigungen auf diesem Gerät aktiviert');await renderNotifications();}}catch(e){toast(e?.message||'Push-Registrierung fehlgeschlagen',5000);if(document.body.contains(register))register.disabled=false;}};
    if(unregister)unregister.onclick=async()=>{unregister.disabled=true;try{const subscription=await localPushSubscription();if(!subscription)throw new Error('Dieses Gerät ist aktuell nicht für Push-Benachrichtigungen registriert.');const result=await api('/PushSubscription/Unregister',{method:'DELETE',body:JSON.stringify(subscriptionRegistration(subscription))});const error=errorText(result);if(error)toast(error);else{await subscription.unsubscribe();toast('Push-Benachrichtigungen auf diesem Gerät deaktiviert');await renderNotifications();}}catch(e){toast(e?.message||'Push-Deaktivierung fehlgeschlagen',5000);if(document.body.contains(unregister))unregister.disabled=false;}};
  }

  function readFile(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsDataURL(file);});}
  function resizeImage(data,maxW,maxH){return new Promise(resolve=>{const img=new Image();img.onload=()=>{if(img.width<=maxW&&img.height<=maxH){resolve(data);return;}const ratio=Math.min(maxW/img.width,maxH/img.height),c=document.createElement('canvas');c.width=img.width*ratio;c.height=img.height*ratio;c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL());};img.src=data;});}
  function cropSquare(data){return new Promise(resolve=>{const img=new Image();img.onload=()=>{const size=Math.min(img.width,img.height),c=document.createElement('canvas');c.width=c.height=size;c.getContext('2d').drawImage(img,(img.width-size)/2,(img.height-size)/2,size,size,0,0,size,size);resolve(c.toDataURL());};img.src=data;});}
  function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);}

  function bindRouteLinks(){document.querySelectorAll('[data-route]').forEach(a=>a.onclick=e=>{if(e.button!==0||e.ctrlKey||e.metaKey)return;e.preventDefault();navigate(new URL(a.href,location.href).pathname);});}
  async function renderRoute(){updateShell();const path=stripBase(location.pathname);const known=path==='/'||path==='/login'||path==='/choosedevice'||path==='/inspections'||path==='/defects'||/^\/deviceattributes\/[^/]+\/\d+$/.test(path)||/^\/defect\/\d+\/\d+$/.test(path)||path==='/users'||path.startsWith('/users/')||path==='/notifications';if(!known){console.error(`Cannot match any routes. URL Segment: '${path}'`);content.innerHTML='';return;}try{if(path==='/'){renderWelcome();}else if(path==='/login'){renderLogin();}else if(!requireLogin())return;else if(path==='/choosedevice'){await playgroundPicker('overview');}else if(path==='/inspections'&&state.user?.role==='maintenance'){content.innerHTML=page('Inspektion','<div class="info-box warning">Benutzer der Rolle Wartung dürfen keine Kontrollen durchführen.</div>');}else if(path==='/inspections'){await playgroundPicker('inspection');}else if(path==='/defects'){await renderDefectOverview();}else if(/^\/deviceattributes\/[^/]+\/\d+$/.test(path)){await renderDeviceAttributes(Number(path.split('/').pop()));}else if(/^\/defect\/\d+\/\d+$/.test(path)){const p=path.split('/');await renderDefect(Number(p[2]),Number(p[3]));}else if(path==='/users'){await renderUsers();}else if(path.startsWith('/users/')){await renderUser(decodeURIComponent(path.slice(7)));}else if(path==='/notifications'){await renderNotifications();}bindRouteLinks();content.focus();}catch(e){if(e.status===401){state.user=null;updateShell();navigate('/login',true);}else{console.error(e);content.innerHTML=page('Fehler',`<div class="info-box warning">${esc(e.message||'Unbekannter Fehler')}</div>`);}}}

  document.querySelector('#menu-button').onclick=()=>document.querySelector('#sidenav').classList.toggle('open');document.querySelector('#login-button').onclick=()=>navigate('/login');document.querySelector('#user-chip').onclick=()=>document.querySelector('#user-menu').classList.toggle('hidden');document.querySelector('#notifications-nav').onclick=()=>{document.querySelector('#user-menu').classList.add('hidden');navigate('/notifications');};document.querySelector('#logout-button').onclick=async()=>{try{await api('/account/logout',{method:'POST'});}catch{}await clearPlayground();state.user=null;document.querySelector('#user-menu').classList.add('hidden');updateShell();navigate('/');};window.onpopstate=renderRoute;bindRouteLinks();
  if(!document.cookie.includes(`${HIDE_INFO_COOKIE_NAME}=true`)){const box=document.createElement('div');box.className='cookie';box.innerHTML='<button>X</button>Diese App verwendet Cookies. Nähere Informationen im Impressum.';box.querySelector('button').onclick=()=>{document.cookie=`${HIDE_INFO_COOKIE_NAME}=true; Max-Age=1576800000; SameSite=Lax; Path=${BASE_PATH || '/'}`;box.remove();};document.body.appendChild(box);}
  if(window.SERVICE_WORKER_ENABLED!==false&&'serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register(withBase('/static/sw.js'),{scope:withBase('/')}).catch(()=>{}));navigator.serviceWorker.addEventListener('message',event=>{const message=event.data?.message||event.data;if(message?.title)toast(message.title,6000);else if(message?.notification?.title)toast(message.notification.title,6000);});}
  loadStoredPlayground().then(async pg=>{state.selectedPlayground=pg;try{state.user=prepareUser(await api('/account/me'));}catch(e){if(e.status!==401)console.error(e);}renderRoute();});
})();
